var ASSISTANT_SESSIONS_STORAGE_KEY = "stgorge_assistant_sessions";
var INITIAL_BOT_TEXT = "سلام ونعمة ✝️ أنا المساعد الذكي لفصل الشهيد مارجرجس.\nأفهم بيانات المخدومين والحضور والغياب وأعياد الميلاد والافتقاد، وأقدر أنفذ أوامر واضحة لتسجيل الحضور والغياب والافتقاد الجماعي (مكالمة أو واتساب أو زيارة منزلية)، وأفتح كروت المخدومين للتعديل، مع استخدام قاعدة البيانات المحلية وطابور المزامنة.";
function createInitialBotMessage() {
	return {
		id: `welcome-${generateUUID()}`,
		role: "bot",
		text: INITIAL_BOT_TEXT,
		actions: [
			{
				label: "📊 عرض الإحصائيات",
				type: "prompt",
				payload: "إحصائيات"
			},
			{
				label: "🎂 أعياد الميلاد",
				type: "prompt",
				payload: "أعياد الميلاد"
			},
			{
				label: "⚠️ الغائبون",
				type: "prompt",
				payload: "الغائبون"
			}
		],
		timestamp: Date.now()
	};
}
/**
* Creates a brand-new, clean Assistant Session with its own isolated ID,
* timestamps, and fresh welcome message.
*/
function createFreshAssistantSession() {
	const sessionId = `session_${generateUUID()}`;
	const now = Date.now();
	return {
		id: sessionId,
		title: "محادثة جديدة",
		createdAt: now,
		updatedAt: now,
		messages: [createInitialBotMessage()]
	};
}
/**
* Retrieves all stored past assistant sessions from localStorage,
* ordered by most recently updated first.
*/
function getStoredAssistantSessions() {
	try {
		if (typeof localStorage === "undefined") return [];
		const raw = localStorage.getItem(ASSISTANT_SESSIONS_STORAGE_KEY);
		if (!raw) return [];
		const parsed = JSON.parse(raw);
		if (!Array.isArray(parsed)) return [];
		return parsed.sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
	} catch (e) {
		console.error("Failed to parse stored assistant sessions:", e);
		return [];
	}
}
/**
* Saves or updates a session in persistent storage.
* Note: Only sessions with at least one user interaction are archived to prevent spamming empty sessions.
*/
function saveAssistantSession(session) {
	try {
		if (typeof localStorage === "undefined") return;
		if (!session.messages.some((m) => m.role === "user")) return;
		const sessions = getStoredAssistantSessions();
		const existingIndex = sessions.findIndex((s) => s.id === session.id);
		let updatedTitle = session.title;
		if (updatedTitle === "محادثة جديدة") {
			const firstUserMsg = session.messages.find((m) => m.role === "user");
			if (firstUserMsg && firstUserMsg.text.trim()) {
				const text = firstUserMsg.text.trim();
				updatedTitle = text.length > 36 ? `${text.slice(0, 34)}...` : text;
			}
		}
		const updatedSession = {
			...session,
			title: updatedTitle,
			updatedAt: Date.now()
		};
		if (existingIndex >= 0) sessions[existingIndex] = updatedSession;
		else sessions.unshift(updatedSession);
		const capped = sessions.slice(0, 50);
		localStorage.setItem(ASSISTANT_SESSIONS_STORAGE_KEY, JSON.stringify(capped));
	} catch (e) {
		console.error("Failed to save assistant session:", e);
	}
}
/**
* Deletes a session by its unique ID from persistent history.
*/
function deleteAssistantSession(sessionId) {
	try {
		if (typeof localStorage === "undefined") return;
		const sessions = getStoredAssistantSessions().filter((s) => s.id !== sessionId);
		localStorage.setItem(ASSISTANT_SESSIONS_STORAGE_KEY, JSON.stringify(sessions));
	} catch (e) {
		console.error("Failed to delete assistant session:", e);
	}
}
/**
* Checks if a user's query explicitly asks about past chats/history.
*/
function isExplicitHistoryRequest(query) {
	const q = (query || "").toLowerCase().trim();
	return [
		"المحادثات السابقة",
		"المحادثه السابقه",
		"الجلسات السابقة",
		"الجلسه السابقه",
		"سجل المحادثات",
		"تاريخ المحادثات",
		"المحادثات القديمة",
		"سجل الشات",
		"سجل الاسئلة",
		"تاريخ الشات",
		"السجلات القديمة"
	].some((t) => q.includes(t));
}
